#!/usr/bin/env python3
import sys, re, io
path = sys.argv[1]
try:
    s = open(path, encoding='utf-8').read()
except FileNotFoundError:
    print("!!! NO OUTPUT FILE: " + path); sys.exit(1)
m = re.search(r'<div class="content-html e-content">', s)
if not m:
    print("!!! NO CONTENT DIV"); sys.exit(1)
start = m.end()
# balance divs
i = start
depth = 1
tagre = re.compile(r'</?div\b', re.I)
while True:
    mm = tagre.search(s, i)
    if not mm:
        break
    if mm.group(0).lower().startswith('</'):
        depth -= 1
        if depth == 0:
            print(s[start:mm.start()])
            sys.exit(0)
    else:
        depth += 1
    i = mm.end()
print("!!! UNBALANCED")

